package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;import java.util.*;
public class Fl01PlatformItem extends BlockItem{
 public Fl01PlatformItem(Block b,Properties p){super(b,p);}public static Direction face(Player p,ItemStack s){var f=p==null?Direction.SOUTH:p.getDirection();for(int i=0;i<(Fl01Item.data(s).getInt("Rotation")&3);i++)f=f.getClockWise();return f;}
 public static BlockPos anchor(BlockPos p,Direction f){return p.relative(f,5);}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown()){if(!c.getLevel().isClientSide){var n=Fl01Item.data(c.getItemInHand());n.putInt("Rotation",(n.getInt("Rotation")+1)&3);Fl01Item.data(c.getItemInHand(),n);}return InteractionResult.SUCCESS;}return super.useOn(c);}
 @Override public BlockPlaceContext updatePlacementContext(BlockPlaceContext c){if(c.getClickedFace()!=Direction.UP)return null;var root=anchor(c.getClickedPos(),face(c.getPlayer(),c.getItemInHand()));return new BlockPlaceContext(c.getLevel(),c.getPlayer(),c.getHand(),c.getItemInHand(),new BlockHitResult(Vec3.atCenterOf(root),Direction.UP,root,false));}
 public static String check(Level l,BlockPos root,Direction f,Player p,ItemStack s){var g=Fl01Geometry.PLATFORM;var bounds=Fl01Geometry.transform(Fl01Geometry.world(root,f),g.bounds);if(bounds.minY<l.getMinBuildHeight()||bounds.maxY>=l.getMaxBuildHeight())return "HEIGHT";for(var at:BlockPos.betweenClosed(BlockPos.containing(bounds.minX,bounds.minY,bounds.minZ),BlockPos.containing(bounds.maxX,bounds.maxY,bounds.maxZ))){if(!l.hasChunkAt(at))return "UNLOADED";if(!l.getWorldBorder().isWithinBounds(at)||p!=null&&(!l.mayInteract(p,at)||!p.mayUseItemAt(at,Direction.UP,s)))return "DENIED";if(!l.getBlockState(at).isAir())return "BLOCKED";}for(var c:g.support){var at=Fl01Geometry.offset(root,f,c).below();if(!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP))return "FOUNDATION";}if(!l.getEntities((net.minecraft.world.entity.Entity)null,bounds,e->!e.isSpectator()&&!(e instanceof net.minecraft.world.entity.item.ItemEntity)).isEmpty())return "OCCUPIED";return "";}
 @Override protected boolean canPlace(BlockPlaceContext c,BlockState s){var reason=check(c.getLevel(),c.getClickedPos(),s.getValue(Fl01PlatformBlock.FACING),c.getPlayer(),c.getItemInHand());if(!reason.isEmpty()&&c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.translatable("defense.status."+reason),true);return reason.isEmpty()&&super.canPlace(c,s);}
 @Override protected boolean placeBlock(BlockPlaceContext c,BlockState s){var done=new ArrayList<BlockPos>();Fl01PlatformBlock.MUTATING.set(true);try{for(int i=0;i<Fl01Geometry.PLATFORM.cells.length;i++){var at=Fl01Geometry.PLATFORM.cell(c.getClickedPos(),s.getValue(Fl01PlatformBlock.FACING),i);if(!c.getLevel().setBlock(at,s.setValue(Fl01PlatformBlock.PART,i),3)){for(var undo:done)c.getLevel().removeBlock(undo,false);return false;}done.add(at);}return true;}finally{Fl01PlatformBlock.MUTATING.set(false);}}
 @Override public void appendHoverText(ItemStack s,Item.TooltipContext l,List<Component>t,TooltipFlag f){t.add(Component.literal("FL-01 platform • one aircraft • coordinates launch"));t.add(Component.literal("Sneak + use: rotate preview. Place on a level foundation."));}
}
